class Provider {
  constructor() {
    this.api = 'https://onisaga.com';
  }

  getSettings() {
    return { supportsMultiLanguage: false, supportsMultiScanlator: false };
  }

  async fetchWithHeaders(url) {
    return fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8',
        'Referer': this.api
      }
    });
  }

  async search(opts) {
    const query = opts.query || '';
    const searchUrl = `${this.api}/search?q=${encodeURIComponent(query)}`;
    try {
      const resp = await this.fetchWithHeaders(searchUrl);
      if (!resp.ok) return [];
      const html = await resp.text();
      const mangas = [];
      const seen = new Set();

      const regex = /href="(\/(?:series|comics|manga)\/[^"]+)"[^>]*>\s*<img[^>]*src="([^"]+)"[^>]*alt="([^"]+)"/gi;
      let match;
      while ((match = regex.exec(html)) !== null) {
        const path = match[1];
        const cover = match[2];
        const title = match[3];
        if (seen.has(path)) continue;
        seen.add(path);
        mangas.push({
          id: path,
          title: title.trim(),
          image: cover.startsWith('http') ? cover : `${this.api}${cover}`,
        });
      }

      if (mangas.length === 0) {
        const fallbackRegex = /<a[^>]*href="(\/(?:series|comics|manga)\/[^"]+)"[^>]*>([^<]+)<\/a>/gi;
        let fMatch;
        while ((fMatch = fallbackRegex.exec(html)) !== null) {
          const fPath = fMatch[1];
          const fTitle = fMatch[2].trim();
          if (fTitle && !seen.has(fPath) && fTitle.length > 2) {
            seen.add(fPath);
            mangas.push({
              id: fPath,
              title: fTitle,
              image: ''
            });
          }
        }
      }
      return mangas;
    } catch (e) {
      console.error('OniSaga search error:', e);
      return [];
    }
  }

  async findChapters(mangaId) {
    const mangaUrl = mangaId.startsWith('http') ? mangaId : `${this.api}${mangaId}`;
    try {
      const resp = await this.fetchWithHeaders(mangaUrl);
      if (!resp.ok) return [];
      const html = await resp.text();
      const chapters = [];
      const seen = new Set();

      const regex = /href="(\/(?:series|comics|manga|read)\/[^"]+)"[^>]*>(?:[^<]*)(?:Chapter|Ch\.)\s*([0-9.]+)/gi;
      let match;
      while ((match = regex.exec(html)) !== null) {
        const path = match[1];
        const num = match[2];
        if (seen.has(num)) continue;
        seen.add(num);
        chapters.push({
          id: path.startsWith('http') ? path : `${this.api}${path}`,
          title: `Chapter ${num}`,
          chapter: num
        });
      }
      return chapters.sort((a, b) => parseFloat(a.chapter) - parseFloat(b.chapter));
    } catch (e) {
      console.error('OniSaga findChapters error:', e);
      return [];
    }
  }

  async findChapterPages(chapterUrl) {
    const url = chapterUrl.startsWith('http') ? chapterUrl : `${this.api}${chapterUrl}`;
    try {
      const resp = await this.fetchWithHeaders(url);
      if (!resp.ok) return [];
      const html = await resp.text();
      const pages = [];
      const seen = new Set();

      const imgRegex = /<img[^>]*src="(https?:\/\/[^"]+\.(?:jpg|jpeg|png|webp))[^"]*"/gi;
      let match;
      let idx = 0;
      while ((match = imgRegex.exec(html)) !== null) {
        const imgUrl = match[1];
        if (seen.has(imgUrl) || imgUrl.includes('logo') || imgUrl.includes('avatar') || imgUrl.includes('icon')) continue;
        seen.add(imgUrl);
        pages.push({
          url: imgUrl,
          index: idx++,
          headers: { Referer: this.api }
        });
      }
      return pages;
    } catch (e) {
      console.error('OniSaga findChapterPages error:', e);
      return [];
    }
  }
}
